-- Fix: Insert missing options for autogenerated questions (Q61-Q1000)
-- This script adds 4 options to each of the 1000 autogenerated questions
-- Run this in Supabase SQL editor to fix the broken seed

BEGIN;

-- Get the quiz ID and add options for all questions that don't have them yet
WITH quiz_questions AS (
  SELECT id, order_index
  FROM public.public_quiz_questions
  WHERE quiz_id = (
    SELECT id FROM public.public_quizzes 
    WHERE title = 'Pupil Enlightenment — General Knowledge'
  )
  AND id NOT IN (
    SELECT DISTINCT question_id FROM public.public_quiz_options
  ) -- All questions without options (both curated and autogenerated)
),
expanded_options AS (
  SELECT 
    qq.id,
    qq.order_index,
    opt_num,
    format('Option %s for Q%s', 
      CASE WHEN opt_num = 1 THEN 'A' WHEN opt_num = 2 THEN 'B' WHEN opt_num = 3 THEN 'C' ELSE 'D' END,
      qq.order_index
    ) AS opt_text,
    ((qq.order_index % 4) + 1) = opt_num AS is_correct
  FROM quiz_questions qq
  CROSS JOIN generate_series(1, 4) AS opt_num
)
INSERT INTO public.public_quiz_options (question_id, option_text, is_correct, order_index)
SELECT id, opt_text, is_correct, opt_num FROM expanded_options;

COMMIT;
